      colorBehaviour.calculate = jest.fn((p, t, i) => {
        colorBehaviour.energy = 0.5;
      });

      colorBehaviour.applyBehaviour(particle, time, index);

      // At midpoint, we expect middle values between red (255,0,0) and blue (0,0,255)
      // r: 0 + (255 - 0) * 0.5 = 127.5 -> 127 (after bitwise operation)
      // g: 0 + (0 - 0) * 0.5 = 0
      // b: 255 + (0 - 255) * 0.5 = 127.5 -> 127 (after bitwise operation)
      expect(particle.rgb.r).toBe(127);
      expect(particle.rgb.g).toBe(0);
      expect(particle.rgb.b).toBe(127);
    });

    it('should use colorA directly when b is not defined', () => {
