      const colorBehaviourWithoutB = new Color(
        { r: 255, g: 0, b: 0 }, // a - red
        null, // b - null
        1000, // life
        null // easing
      );

      colorBehaviourWithoutB.applyBehaviour(particle, time, index);

      // Should directly use colorA values
      expect(particle.rgb.r).toBe(255);
      expect(particle.rgb.g).toBe(0);
      expect(particle.rgb.b).toBe(0);
    });

    it('should handle different energy values correctly', () => {
      // Test with energy = 0 (should be all colorB)
      colorBehaviour.calculate = jest.fn((p, t, i) => {
        colorBehaviour.energy = 0;
      });

      colorBehaviour.applyBehaviour(particle, time, index);

      expect(particle.rgb.r).toBe(0);
      expect(particle.rgb.g).toBe(0);
      expect(particle.rgb.b).toBe(255);

      // Reset particle
      particle.rgb = { r: 0, g: 0, b: 0 };

      // Test with energy = 1 (should be all colorA)
      colorBehaviour.calculate = jest.fn((p, t, i) => {
        colorBehaviour.energy = 1;
